import './App.css';
import { useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import Nickname from './Nickname';
import RoomInfo from './RoomInfo';
import Board from './Board';
import Ended from './Ended'; // Importujte komponentu Ended

function App() {
  const [socket, setSocket] = useState(null);
  const [roomCode, setRoomCode] = useState("");
  const [showNickname, setShowNickname] = useState(false);
  const [ownerName, setOwnerName] = useState('');
  const [nickname, setNickname] = useState('');
  const [roomData, setRoomData] = useState(null);
  const [isCreateMode, setIsCreateMode] = useState(false);
  const [fillWithBots, setFillWithBots] = useState(false);
  const [gameData, setGameData] = useState(null);
  const [gameStarted, setGameStarted] = useState(false);
  const [gameOver, setGameOver] = useState(false); // Přidání stavu pro ukončenou hru
  const [statusMessage, setStatusMessage] = useState("");

  useEffect(() => {
    const socket = io('http://127.0.0.1:5000');
    setSocket(socket);

    socket.on('connect', () => {
      console.log('Successfully connected, socket id is ', socket.id);
    });

    socket.on('disconnect', () => {
      console.log('You have been disconnected from the server.');
    });

    socket.on('session:joined', (response) => {
      console.log('Přijatá odpověď při připojení:', response);
      if (response && response.id && response.name) {
        const newPlayer = {
          id: response.id,
          name: response.name,
          color: response.color || null,
        };
        setStatusMessage(`${response.name} joined`);

        setRoomData((prevRoomData) => {
          const updatedPlayers = prevRoomData ? [...prevRoomData.players, newPlayer] : [newPlayer];
          return {
            key: prevRoomData ? prevRoomData.key : '',
            players: updatedPlayers,
          };
        });
      }
    });

    socket.on('session:created', (response) => {
      console.log('Key room:', response.key);
      if (response && response.key && Array.isArray(response.players) && response.owner) {
        setRoomData({
          key: response.key,
          players: response.players,
        });
        setOwnerName(response.owner.name);
      }
    });

    socket.on('game:started', (gameState) => {
      console.log('Hra byla zahájena, herní stav:', gameState);
      setGameData(gameState);
      setGameStarted(true);
    });

    socket.on('game:ended', () => {
      console.log('Hra byla ukončena');
      setGameOver(true); // Nastavení stavu, že hra skončila
    });

    return () => {
      socket.disconnect();
    };
  }, [roomCode]);

  const createRoom = () => {
    if (socket) {
      setIsCreateMode(true);
      setShowNickname(true);
    }
  };

  const joinRoom = () => {
    if (socket && roomCode) {
      setIsCreateMode(false);
      setShowNickname(true);
    }
  };

  const handleNicknameSubmit = (nickname) => {
    setNickname(nickname);
    const roomData = {
      name: nickname,
      key: roomCode || undefined,
    };

    if (!isCreateMode && roomCode) {
      socket.emit('session:join', roomData, (response) => {
        console.log('Odpověď na připojení:', response);
        if (response && response.key && Array.isArray(response.players)) {
          setRoomData({
            key: response.key,
            players: response.players,
          });
          setOwnerName(response.owner.name || '');
        }
      });
    } else if (isCreateMode) {
      socket.emit('session:create', roomData, (response) => {
        console.log('Místnost byla vytvořena!', response);
        if (response && response.key && Array.isArray(response.players) && response.owner) {
          setRoomData({
            key: response.key,
            players: response.players,
          });
          setOwnerName(response.owner.name || '');
        }
      });
    }

    setShowNickname(false);
  };

  const startGame = () => {
    if (socket && ownerName === nickname) {
      const payload = {
        fillWithBots: fillWithBots,
      };

      socket.emit('game:start', payload, (response) => {
        console.log('Odpověď na start game:', response);

        if (response) {
          setGameData(response.gameState);
          setGameStarted(true);
        }
      });
    }
  };

  const returnToApp = () => {
    setGameOver(false);
    setGameStarted(false);
    setRoomData(null); // Nebo jiný stav pro reset
    setRoomCode('');
    setNickname('');
  };

  return (
    <div className="App">
      <header className="App-header">
        {!gameStarted && !gameOver && <h1>Člověče, nezlob se! online s přáteli</h1>}
      </header>

      <div className="button-container">
        {!gameStarted && !gameOver ? (
          <>
            {statusMessage && <div className="status-message">{statusMessage}</div>}

            {!showNickname && !roomData ? (
              <>
                <input
                  type="text"
                  placeholder="Zadejte kód místnosti"
                  value={roomCode}
                  onChange={(e) => setRoomCode(e.target.value)}
                />
                <button onClick={joinRoom}>Join in</button>
                <button onClick={createRoom}>Create Room</button>
              </>
            ) : showNickname ? (
              <Nickname onSubmit={handleNicknameSubmit} />
            ) : roomData && roomData.players && roomData.players.length > 0 ? (
              <>
                <RoomInfo
                  roomCode={roomData.key}
                  players={roomData.players}
                  ownerName={ownerName}
                />
                {ownerName === nickname && (
                  <div>
                    <button onClick={startGame}>Start Game</button>
                    <label>
                      <input
                        type="checkbox"
                        checked={fillWithBots}
                        onChange={() => setFillWithBots(!fillWithBots)}
                      />
                      Fill with bots
                    </label>
                  </div>
                )}
              </>
            ) : (
              <p>Probíhá připojování do místnosti...</p>
            )}
          </>
        ) : gameOver ? (
          // Pokud je hra ukončena, zobrazí se komponenta Ended a tlačítko pro návrat
          <Ended onReturnToApp={returnToApp} />
        ) : (
          // Pokud hra probíhá, zobrazí se komponenta Board
          <Board socket={socket} gameData={gameData} roomCode={roomCode} />
        )}
      </div>
    </div>
  );
}

export default App;
